// Library code, shipped as a package
public class OrdersClient(HttpClient http)
{
    public async Task<string> GetTitleAsync(int id)
    {
        var order = await http.GetFromJsonAsync<Order>($"orders/{id}");
        return $"Order {order!.Id}: {order.Total:C}";
    }
}

// App code: a desktop view model
public class OrderViewModel(OrdersClient client)
{
    // On the UI thread, the await above waits for this thread: deadlock
    public string Title => client.GetTitleAsync(42).Result;
}

// Library code: it never needs the caller's context
public class OrdersClient(HttpClient http)
{
    public async Task<string> GetTitleAsync(int id)
    {
        var order = await http.GetFromJsonAsync<Order>($"orders/{id}")
            .ConfigureAwait(false);
        return $"Order {order!.Id}: {order.Total:C}";
    }
}

// App code: no ConfigureAwait, so Title is set back on the UI thread
public class OrderViewModel(OrdersClient client)
{
    public string Title { get; private set; } = "";
    public async Task LoadAsync() => Title = await client.GetTitleAsync(42);
}
